def compute(vars):
    debt_2016 = vars["v1"]
    debt_2017 = vars["v2"]
    total_debt_maturities = vars["v3"]

    if total_debt_maturities == 0:
        return None

    combined_maturities = debt_2016 + debt_2017
    value = combined_maturities / total_debt_maturities * 100

    return {
        "value": value,
        "trace": {
            "combined_maturities": combined_maturities,
            "total_debt_maturities": total_debt_maturities,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
